from pwn import *

HOST = 'android-dropper.csaw.io'
PORT = 3000

batches = [
    # (Description, List of 30 inputs)
    ("1. 'csawctf' then 29 lines of '0'", ['csawctf'] + ['0'] * 29),
    ("2. '1337' for all 30 lines", ['1337'] * 30),
    ("3. '999999999999999999' for all 30 lines", ['999999999999999999'] * 30),
    ("4. '125' for all 30 lines", ['125'] * 30),
]

results = []

for batch_name, batch_inputs in batches:
    output = ''
    try:
        conn = remote(HOST, PORT)
        for line in batch_inputs:
            conn.sendline(line.encode())
        # Allow for multiple outputs, safe recv limit
        try:
            while True:
                out = conn.recv(timeout=2)
                if not out:
                    break
                output += out.decode('utf-8', errors='ignore')
        except EOFError:
            pass
        conn.close()
    except Exception as e:
        output += f"\n[Exception] {str(e)}\n"
    results.append((batch_name, output))

for desc, out in results:
    print(f"{'='*60}\n{desc}\n{'='*60}\n{out}\n")

from pwn import *

# Set context
context.log_level = 'critical'

HOST, PORT = 'android-dropper.csaw.io', 3000

def run_case(inputs):
    io = remote(HOST, PORT)
    outputs = []
    for value in inputs:
        try:
            line = io.recvline(timeout=2)
            if line is not None:
                outputs.append(line.decode(errors='ignore').strip())
            else:
                outputs.append('<NO PROMPT>')
            io.sendline(str(value))
        except Exception as e:
            outputs.append(f'<EXCEPTION {e}>')
            break
    try:
        while True:
            more = io.recvline(timeout=1)
            if more:
                outputs.append(more.decode(errors='ignore').strip())
            else:
                break
    except Exception:
        pass
    io.close()
    return outputs

def case1():
    return run_case(['-2147483648']*30)

def case2():
    return run_case(['2147483647']*30)

def case3():
    return run_case(['0']*29 + ['1'])

if __name__ == "__main__":
    print('---Test Case 1: -2147483648 x 30---')
    out1 = case1()
    for line in out1:
        print(line)
    print('---Test Case 2: 2147483647 x 30---')
    out2 = case2()
    for line in out2:
        print(line)
    print('---Test Case 3: 0 x 29, 1 x 1---')
    out3 = case3()
    for line in out3:
        print(line)
